/**
 * frontend/src/components/App.jsx
 * VERSION FINALE - #00BFFF avec coins arrondis (soft rounded)
 */

import React, { useState, useEffect, useRef } from 'react';
import Login from './pages/Login';
import Dashboard from './Dashboard';
import Enrollment from './Enrollment';
import CameraRecognition from './CameraRecognition';
import authService from './auth_service';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#00BFFF',
  primaryDark: '#0099CC',
  success: '#10B981',
  error: '#EF4444',
  background: '#F8FAFC',
  surface: '#FFFFFF',
  sidebar: 'linear-gradient(180deg, #00BFFF, #0099CC)',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [currentView, setCurrentView] = useState('dashboard');
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showResults, setShowResults] = useState(false);
  const [searchLoading, setSearchLoading] = useState(false);

  const [sidebarOpen, setSidebarOpen] = useState(true);

  const debounceRef = useRef(null);

  useEffect(() => {
    try {
      authService.initialize();
      const user = authService.getUser();
      if (authService.isAuthenticated() && user) {
        setCurrentUser(user);
        setIsAuthenticated(true);
      }
    } catch (err) {
      console.error('Auth init error:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  const addNotification = (message, type = 'info') => {
    const id = Date.now();
    setNotifications((prev) => [...prev, { id, message, type }]);
    setTimeout(() => setNotifications((prev) => prev.filter(n => n.id !== id)), 4000);
  };

  const handleSearch = (value) => {
    setSearchQuery(value);
    if (debounceRef.current) clearTimeout(debounceRef.current);

    if (!value || value.trim().length < 2) {
      setSearchResults([]);
      setShowResults(false);
      return;
    }

    setSearchLoading(true);
    debounceRef.current = setTimeout(async () => {
      try {
        const result = await studentsAPI.search(value);
        if (result.success) {
          setSearchResults(result.data?.results || []);
          setShowResults(true);
        }
      } catch (err) {
        addNotification('Erreur lors de la recherche', 'error');
      } finally {
        setSearchLoading(false);
      }
    }, 400);
  };

  const handleSelectStudent = (student) => {
    if (!student) return;
    setSearchQuery(student.name || 'Inconnu');
    setShowResults(false);
    addNotification(`Étudiant sélectionné : ${student.name}`, 'success');
  };

  const handleLoginSuccess = (user) => {
    setCurrentUser(user);
    setIsAuthenticated(true);
    addNotification(`Bienvenue ${user.first_name || user.username || 'Utilisateur'}`, 'success');
  };

  const handleLogout = async () => {
    await authService.logout().catch(() => {});
    setCurrentUser(null);
    setIsAuthenticated(false);
    setSearchQuery('');
    setSearchResults([]);
    setShowResults(false);
    addNotification('Déconnexion réussie', 'info');
  };

  if (loading) return <div style={styles.loadingScreen}>Chargement...</div>;
  if (!isAuthenticated) return <Login onLoginSuccess={handleLoginSuccess} />;

  const username = currentUser?.first_name || currentUser?.username || 'Utilisateur';
  const role = currentUser?.role || (currentUser?.is_superuser ? 'Administrateur' : 'Utilisateur');

  return (
    <div style={styles.appWrapper}>
      {/* SIDEBAR - Coins plus arrondis */}
      {sidebarOpen && (
        <aside style={styles.sidebar}>
          <div style={styles.brand}>
            <div style={styles.brandIcon}>📡</div>
            <h1 style={styles.brandName}>Attendance OS</h1>
          </div>

          <nav style={styles.nav}>
            <NavItem icon="📊" label="Tableau de Bord" active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} />
            <NavItem icon="👤" label="Enrôlement" active={currentView === 'enrollment'} onClick={() => setCurrentView('enrollment')} />
            <NavItem icon="📸" label="Reconnaissance Faciale" active={currentView === 'camera'} onClick={() => setCurrentView('camera')} />
          </nav>

          <div style={styles.userSection}>
            <div style={styles.userAvatar}>👨‍💼</div>
            <div style={styles.userInfo}>
              <div style={styles.userName}>{username}</div>
              <div style={styles.userRole}>{role}</div>
            </div>
          </div>

          <button onClick={handleLogout} style={styles.logoutBtn}>
            Déconnexion
          </button>
        </aside>
      )}

      {/* MAIN */}
      <main style={styles.main}>
        <header style={styles.topBar}>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} style={styles.menuBtn}>
            ☰
          </button>

          {/* BARRE DE RECHERCHE - Coins très arrondis + style moderne */}
          <div style={{ position: 'relative', width: '460px' }}>
            <div style={styles.searchBar}>
              <span style={styles.searchIcon}>🔍</span>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                placeholder="Rechercher un étudiant par nom ou email..."
                style={styles.searchInput}
              />
              {searchLoading && <span style={styles.loadingIndicator}>●●●</span>}
            </div>

            {showResults && (
              <div style={styles.searchDropdown}>
                {searchResults.length === 0 ? (
                  <div style={styles.emptyResult}>Aucun résultat trouvé</div>
                ) : (
                  searchResults.map((student, i) => (
                    <div key={i} style={styles.searchResultItem} onClick={() => handleSelectStudent(student)}>
                      <div style={{ fontWeight: 600 }}>{student.name}</div>
                      <div style={{ fontSize: '0.85rem', color: COLORS.textMuted }}>
                        ID: {student.student_id}
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}
          </div>
        </header>

        <div style={styles.contentArea}>
          {currentView === 'dashboard' && <Dashboard addNotification={addNotification} />}
          {currentView === 'enrollment' && <Enrollment addNotification={addNotification} />}
          {currentView === 'camera' && <CameraRecognition addNotification={addNotification} />}
        </div>
      </main>

      {/* TOAST NOTIFICATIONS */}
      <div style={styles.toastContainer}>
        {notifications.map((notif) => (
          <div
            key={notif.id}
            style={{
              ...styles.toast,
              backgroundColor: notif.type === 'success' ? COLORS.success : 
                               notif.type === 'error' ? COLORS.error : COLORS.primary,
            }}
          >
            {notif.message}
          </div>
        ))}
      </div>
    </div>
  );
};

